import struct, subprocess, sys

LRI=0x2066; RLI=0x2067; FSI=0x2068; PDI=0x2069

def make_input(chars):
    return b''.join(struct.pack('<I', c) for c in chars)

def run(data, name):
    with open('/tmp/inp.bin','wb') as f:
        f.write(data)
    r = subprocess.run(['/tmp/harness','/tmp/inp.bin'], capture_output=True)
    if r.returncode != 0:
        print(f"CRASH {name} rc={r.returncode}")
        print(r.stderr.decode()[:2000])
        return True
    return False

# Test nested isolates
for depth in [60, 100, 120, 124, 125, 130, 200]:
    chars = [LRI]*depth + [PDI]*depth
    if run(make_input(chars), f"nested-LRI-{depth}"):
        break
EOF
